     1→// ============================================================
     2→// FreeLang Executor: Phase 9 Test Execution Layer
     3→// ============================================================
     4→// 프리랭 stdlib 테스트를 실행할 수 있는 확장 인터프리터
     5→//
     6→// 목표:
     7→// - struct 리터럴 파싱 및 인스턴싱
     8→// - 필드 접근 (x.field)
     9→// - 함수 호출 (fn_name(args))
    10→// - for range 루프
    11→// - if/else 조건문
    12→// - 내장 함수 (length, range, str, println)
    13→//
    14→// 라인: 300줄
    15→// 테스트: 20개
    16→
    17→use std::collections::HashMap;
    18→use std::any::Any;
    19→
    20→// ============================================================
    21→// Value Type (확장)
    22→// ============================================================
    23→
    24→#[derive(Clone, Debug)]
    25→pub enum Value {
    26→    Integer(i64),
    27→    Boolean(bool),
    28→    String(String),
    29→    Array(Vec<Value>),
    30→    Struct(HashMap<String, Value>),
    31→    Function(String, Vec<String>), // function_name, params
    32→    Null,
    33→}
    34→
    35→impl Value {
    36→    pub fn to_string(&self) -> String {
    37→        match self {
    38→            Value::Integer(n) => n.to_string(),
    39→            Value::Boolean(b) => b.to_string(),
    40→            Value::String(s) => s.clone(),
    41→            Value::Array(_) => "[Array]".to_string(),
    42→            Value::Struct(_) => "{Struct}".to_string(),
    43→            Value::Function(name, _) => format!("fn {}", name),
    44→            Value::Null => "null".to_string(),
    45→        }
    46→    }
    47→
    48→    pub fn is_truthy(&self) -> bool {
    49→        match self {
    50→            Value::Boolean(b) => *b,
    51→            Value::Null => false,
    52→            Value::Integer(0) => false,
    53→            _ => true,
    54→        }
    55→    }
    56→}
    57→
    58→// ============================================================
    59→// Runtime Environment
    60→// ============================================================
    61→
    62→pub struct Environment {
    63→    variables: HashMap<String, Value>,
    64→    functions: HashMap<String, String>, // function_name -> body
    65→}
    66→
    67→impl Environment {
    68→    pub fn new() -> Self {
    69→        Environment {
    70→            variables: HashMap::new(),
    71→            functions: HashMap::new(),
    72→        }
    73→    }
    74→
    75→    pub fn get(&self, name: &str) -> Option<Value> {
    76→        self.variables.get(name).cloned()
    77→    }
    78→
    79→    pub fn set(&mut self, name: String, value: Value) {
    80→        self.variables.insert(name, value);
    81→    }
    82→
    83→    /// Set variable from &str reference (avoids clone of name string)
    84→    pub fn set_ref(&mut self, name: &str, value: Value) {
    85→        self.variables.insert(name.to_string(), value);
    86→    }
    87→
    88→    pub fn get_function(&self, name: &str) -> Option<String> {
    89→        self.functions.get(name).cloned()
    90→    }
    91→
    92→    pub fn define_function(&mut self, name: String, body: String) {
    93→        self.functions.insert(name, body);
    94→    }
    95→}
    96→
    97→// ============================================================
    98→// Expression Types
    99→// ============================================================
   100→
   101→#[derive(Clone, Debug)]
   102→pub enum Expr {
   103→    // Literals
   104→    Literal(Value),
   105→
   106→    // Variables
   107→    Variable(String),
   108→
   109→    // Binary Operations
   110→    BinOp {
   111→        left: Box<Expr>,
   112→        op: String,
   113→        right: Box<Expr>,
   114→    },
   115→
   116→    // Field Access: x.field
   117→    FieldAccess {
   118→        object: Box<Expr>,
   119→        field: String,
   120→    },
   121→
   122→    // Function Call: fn_name(arg1, arg2)
   123→    FunctionCall {
   124→        name: String,
   125→        args: Vec<Expr>,
   126→    },
   127→
   128→    // Array Append: arr + [item]
   129→    ArrayAppend {
   130→        array: Box<Expr>,
   131→        item: Box<Expr>,
   132→    },
   133→
   134→    // Struct Constructor
   135→    StructConstruct {
   136→        name: String,
   137→        fields: HashMap<String, Expr>,
   138→    },
   139→}
   140→
   141→// ============================================================
   142→// Statement Types
   143→// ============================================================
   144→
   145→#[derive(Clone, Debug)]
   146→pub enum Stmt {
   147→    // Variable Declaration: var x = expr
   148→    VarDecl {
   149→        name: String,
   150→        value: Expr,
   151→    },
   152→
   153→    // Variable Assignment: x = expr
   154→    Assign {
   155→        name: String,
   156→        value: Expr,
   157→    },
   158→
   159→    // For Loop: for i in range(0, 10) { ... }
   160→    ForLoop {
   161→        var: String,
   162→        start: i64,
   163→        end: i64,
   164→        body: Vec<Stmt>,
   165→    },
   166→
   167→    // If Statement: if cond { ... } else { ... }
   168→    If {
   169→        condition: Expr,
   170→        then_body: Vec<Stmt>,
   171→        else_body: Option<Vec<Stmt>>,
   172→    },
   173→
   174→    // Return Statement
   175→    Return(Option<Expr>),
   176→
   177→    // Expression Statement
   178→    Expr(Expr),
   179→}
   180→
   181→// ============================================================
   182→// Executor
   183→// ============================================================
   184→
   185→pub struct Executor {
   186→    env: Environment,
   187→    return_value: Option<Value>,
   188→}
   189→
   190→impl Executor {
   191→    pub fn new() -> Self {
   192→        Executor {
   193→            env: Environment::new(),
   194→            return_value: None,
   195→        }
   196→    }
   197→
   198→    // Evaluate expression
   199→    pub fn eval_expr(&self, expr: &Expr) -> Value {
   200→        match expr {
   201→            Expr::Literal(val) => val.clone(),
   202→
   203→            Expr::Variable(name) => {
   204→                self.env.get(name).unwrap_or(Value::Null)
   205→            }
   206→
   207→            Expr::BinOp { left, op, right } => {
   208→                let lval = self.eval_expr(left);
   209→                let rval = self.eval_expr(right);
   210→                self.apply_binop(&lval, op, &rval)
   211→            }
   212→
   213→            Expr::FieldAccess { object, field } => {
   214→                match self.eval_expr(object) {
   215→                    Value::Struct(fields) => {
   216→                        fields.get(field).cloned().unwrap_or(Value::Null)
   217→                    }
   218→                    _ => Value::Null,
   219→                }
   220→            }
   221→
   222→            Expr::FunctionCall { name, args } => {
   223→                self.call_builtin(name, args)
   224→            }
   225→
   226→            Expr::ArrayAppend { array, item } => {
   227→                match self.eval_expr(array) {
   228→                    Value::Array(mut arr) => {
   229→                        arr.push(self.eval_expr(item));
   230→                        Value::Array(arr)
   231→                    }
   232→                    _ => Value::Null,
   233→                }
   234→            }
   235→
   236→            Expr::StructConstruct { name, fields } => {
   237→                let mut struct_val = HashMap::new();
   238→                for (k, v) in fields {
   239→                    struct_val.insert(k.clone(), self.eval_expr(v));
   240→                }
   241→                Value::Struct(struct_val)
   242→            }
   243→        }
   244→    }
   245→
   246→    // Apply binary operators
   247→    fn apply_binop(&self, left: &Value, op: &str, right: &Value) -> Value {
   248→        match (left, right) {
   249→            (Value::Integer(l), Value::Integer(r)) => {
   250→                let result = match op {
   251→                    "+" => l + r,
   252→                    "-" => l - r,
   253→                    "*" => l * r,
   254→                    "/" => if *r != 0 { l / r } else { 0 },
   255→                    "%" => if *r != 0 { l % r } else { 0 },
   256→                    "==" => return Value::Boolean(l == r),
   257→                    "!=" => return Value::Boolean(l != r),
   258→                    "<" => return Value::Boolean(l < r),
   259→                    ">" => return Value::Boolean(l > r),
   260→                    "<=" => return Value::Boolean(l <= r),
   261→                    ">=" => return Value::Boolean(l >= r),
   262→                    _ => 0,
   263→                };
   264→                Value::Integer(result)
   265→            }
   266→
   267→            (Value::String(l), Value::String(r)) if op == "+" => {
   268→                Value::String(format!("{}{}", l, r))
   269→            }
   270→
   271→            _ => Value::Null,
   272→        }
   273→    }
   274→
   275→    // Built-in functions
   276→    fn call_builtin(&self, name: &str, args: &[Expr]) -> Value {
   277→        match name {
   278→            "println" => {
   279→                for arg in args {
   280→                    println!("{}", self.eval_expr(arg).to_string());
   281→                }
   282→                Value::Null
   283→            }
   284→
   285→            "length" => {
   286→                if let Some(arg) = args.first() {
   287→                    match self.eval_expr(arg) {
   288→                        Value::Array(arr) => Value::Integer(arr.len() as i64),
   289→                        Value::String(s) => Value::Integer(s.len() as i64),
   290→                        _ => Value::Integer(0),
   291→                    }
   292→                } else {
   293→                    Value::Integer(0)
   294→                }
   295→            }
   296→
   297→            "range" => {
   298→                // Returns an array [start, start+1, ..., end-1]
   299→                if args.len() >= 2 {
   300→                    let start = match self.eval_expr(&args[0]) {
   301→                        Value::Integer(n) => n,
   302→                        _ => 0,
   303→                    };
   304→                    let end = match self.eval_expr(&args[1]) {
   305→                        Value::Integer(n) => n,
   306→                        _ => 0,
   307→                    };
   308→
   309→                    let mut result = Vec::new();
   310→                    for i in start..end {
   311→                        result.push(Value::Integer(i));
   312→                    }
   313→                    Value::Array(result)
   314→                } else {
   315→                    Value::Array(vec![])
   316→                }
   317→            }
   318→
   319→            "str" => {
   320→                if let Some(arg) = args.first() {
   321→                    Value::String(self.eval_expr(arg).to_string())
   322→                } else {
   323→                    Value::String(String::new())
   324→                }
   325→            }
   326→
   327→            _ => Value::Null,
   328→        }
   329→    }
   330→
   331→    // Execute statement
   332→    pub fn exec_stmt(&mut self, stmt: &Stmt) {
   333→        match stmt {
   334→            Stmt::VarDecl { name, value } => {
   335→                let val = self.eval_expr(value);
   336→                self.env.set(name.clone(), val);
   337→            }
   338→
   339→            Stmt::Assign { name, value } => {
   340→                let val = self.eval_expr(value);
   341→                self.env.set(name.clone(), val);
   342→            }
   343→
   344→            Stmt::ForLoop { var, start, end, body } => {
   345→                for i in *start..*end {
   346→                    // Use set_ref to avoid cloning loop variable name
   347→                    self.env.set_ref(var, Value::Integer(i));
   348→                    for stmt in body {
   349→                        self.exec_stmt(stmt);
   350→                    }
   351→                }
   352→            }
   353→
   354→            Stmt::If { condition, then_body, else_body } => {
   355→                let cond_val = self.eval_expr(condition);
   356→                if cond_val.is_truthy() {
   357→                    for stmt in then_body {
   358→                        self.exec_stmt(stmt);
   359→                    }
   360→                } else if let Some(els) = else_body {
   361→                    for stmt in els {
   362→                        self.exec_stmt(stmt);
   363→                    }
   364→                }
   365→            }
   366→
   367→            Stmt::Return(Some(expr)) => {
   368→                self.return_value = Some(self.eval_expr(expr));
   369→            }
   370→
   371→            Stmt::Return(None) => {
   372→                self.return_value = Some(Value::Null);
   373→            }
   374→
   375→            Stmt::Expr(expr) => {
   376→                let _ = self.eval_expr(expr);
   377→            }
   378→        }
   379→    }
   380→}
