    10→/// CompileResult: Output from successful compilation
    11→#[derive(Debug, Clone)]
    12→pub struct CompileResult {
    13→    pub work_id: u64,
    14→    pub success: bool,
    15→    pub error_count: usize,
    16→    pub warnings: Vec<String>,
    17→    pub compile_time_ms: u64,
    18→}
    19→
    20→impl CompileResult {
    21→    pub fn success(work_id: u64, time_ms: u64) -> Self {
    22→        CompileResult {
    23→            work_id,
    24→            success: true,
    25→            error_count: 0,
    26→            warnings: Vec::new(),
    27→            compile_time_ms: time_ms,
    28→        }
    29→    }
    30→
    31→    pub fn failure(work_id: u64, error_count: usize, time_ms: u64) -> Self {
    32→        CompileResult {
    33→            work_id,
    34→            success: false,
    35→            error_count,
    36→            warnings: Vec::new(),
    37→            compile_time_ms: time_ms,
    38→        }
    39→    }
    40→}
    41→
    42→/// WorkQueue: Thread-safe queue for distributing work
    43→pub struct WorkQueue {
    44→    queue: Arc<Mutex<VecDeque<WorkItem>>>,
    45→    results: Arc<Mutex<Vec<CompileResult>>>,
    46→}
    47→
    48→impl WorkQueue {
    49→    pub fn new() -> Self {
    50→        WorkQueue {
    51→            queue: Arc::new(Mutex::new(VecDeque::new())),
    52→            results: Arc::new(Mutex::new(Vec::new())),
    53→        }
    54→    }
    55→
    56→    /// Add work item to queue
    57→    pub fn enqueue(&self, work: WorkItem) -> Result<(), String> {
    58→        match self.queue.lock() {
    59→            Ok(mut q) => {
    60→                q.push_back(work);
    61→                Ok(())
    62→            }
    63→            Err(e) => Err(format!("Failed to lock queue: {}", e)),
    64→        }
    65→    }
    66→
    67→    /// Get next work item (O(1))
    68→    pub fn dequeue(&self) -> Option<WorkItem> {
    69→        match self.queue.lock() {
    70→            Ok(mut q) => q.pop_front(),
    71→            Err(_) => None,
    72→        }
    73→    }
    74→
    75→    /// Add result
    76→    pub fn add_result(&self, result: CompileResult) {
    77→        if let Ok(mut results) = self.results.lock() {
    78→            results.push(result);
    79→        }
    80→    }
    81→
    82→    /// Get all results
    83→    pub fn get_results(&self) -> Vec<CompileResult> {
    84→        match self.results.lock() {
    85→            Ok(results) => results.clone(),
    86→            Err(_) => Vec::new(),
    87→        }
    88→    }
    89→
    90→    /// Queue size
    91→    pub fn len(&self) -> usize {
    92→        match self.queue.lock() {
    93→            Ok(q) => q.len(),
    94→            Err(_) => 0,
    95→        }
    96→    }
    97→
    98→    pub fn is_empty(&self) -> bool {
    99→        self.len() == 0
   100→    }
   101→}
   102→
   103→impl Clone for WorkQueue {
   104→    fn clone(&self) -> Self {
   105→        WorkQueue {
   106→            queue: Arc::clone(&self.queue),
   107→            results: Arc::clone(&self.results),
   108→        }
   109→    }
   110→}
