   112→/// Worker: Represents a single compilation worker thread
   113→pub struct Worker {
   114→    id: u32,
   115→    state: Arc<SharedState>,
   116→    queue: WorkQueue,
   117→    active: Arc<AtomicBool>,
   118→}
   119→
   120→impl Worker {
   121→    pub fn new(id: u32, state: Arc<SharedState>, queue: WorkQueue) -> Self {
   122→        Worker {
   123→            id,
   124→            state,
   125→            queue,
   126→            active: Arc::new(AtomicBool::new(true)),
   127→        }
   128→    }
   129→
   130→    /// Tokenize source code into tokens (O(1) cache lookups via HashMap)
   131→    fn tokenize(&self, source: &str) -> Vec<Token> {
   132→        let mut tokens = Vec::new();
   133→        let mut token_id = 0u64;
   134→
   135→        // Phase 1: Generate all tokens without cache lookups
   136→        for (line_idx, line) in source.lines().enumerate() {
   137→            let mut col = 0;
   138→            for word in line.split_whitespace() {
   139→                let token_type = match word {
   140→                    "let" | "fn" | "if" | "else" | "for" | "while" => 0, // keyword
   141→                    _ if word.parse::<i64>().is_ok() => 2, // literal
   142→                    _ => 1, // identifier
   143→                };
   144→
   145→                let token = Token::new(
   146→                    token_id,
   147→                    token_type,
   148→                    word.to_string(),
   149→                    (line_idx + 1) as u32,
   150→                    col,
   151→                );
   152→
   153→                tokens.push(token);
   154→                token_id += 1;
   155→                col += word.len() as u32 + 1;
   156→            }
   157→        }
   158→
   159→        // Phase 2: Single batched cache lookup (mutex acquired once, not per token)
   160→        if let Ok(mut cache) = self.state.token_cache.lock() {
   161→            let mut filtered_tokens = Vec::new();
   162→            for token in &tokens {
   163→                // Check cache once per token (within single lock)
   164→                if let Some(cached) = cache.lookup(token.id) {
   165→                    filtered_tokens.push(cached);
   166→                } else {
   167→                    filtered_tokens.push(token.clone());
   168→                }
   169→            }
   170→            tokens = filtered_tokens;
   171→        }
   172→
   173→        tokens
   174→    }
   175→
   176→    /// Parse tokens into AST-like structure (simplified)
   177→    fn parse(&self, tokens: &[Token]) -> Result<(), String> {
   178→        for token in tokens {
   179→            if token.token_type == 0 && token.value == "let" {
   180→                // Simple variable declaration parsing
   181→                if tokens.len() > 2 {
   182→                    let var = Variable {
   183→                        name: format!("var_{}", token.id),
   184→                        var_type: "i32".to_string(),
   185→                        scope: 0,
   186→                        value: None,
   187→                    };
   188→                    self.state.add_variable(var)?;
   189→                }
   190→            } else if token.token_type == 0 && token.value == "fn" {
   191→                // Simple function declaration parsing
   192→                let func = Function {
   193→                    name: format!("func_{}", token.id),
   194→                    params: Vec::new(),
   195→                    return_type: "i32".to_string(),
   196→                    scope: 0,
   197→                };
   198→                self.state.add_function(func)?;
   199→            }
   200→        }
   201→        Ok(())
   202→    }
   203→
   204→    /// Compile a single work item
   205→    pub fn compile(&self, work: WorkItem) -> CompileResult {
   206→        let start = std::time::Instant::now();
   207→
   208→        // Tokenization phase
   209→        let tokens = self.tokenize(&work.source_code);
   210→        let token_count = tokens.len() as u64;
   211→
   212→        // Update cache with new tokens
   213→        if let Ok(mut cache) = self.state.token_cache.lock() {
   214→            for token in &tokens {
   215→                let _ = cache.insert(token.clone());
   216→            }
   217→        }
   218→
   219→        // Parsing phase
   220→        let parse_result = self.parse(&tokens);
   221→
   222→        let elapsed = start.elapsed().as_millis() as u64;
   223→
   224→        // Update metrics
   225→        self.state.update_metrics(token_count, elapsed * 1_000_000); // Convert to ns
   226→
   227→        match parse_result {
   228→            Ok(_) => CompileResult::success(work.id, elapsed),
   229→            Err(e) => {
   230→                self.state.record_error(e.clone());
   231→                CompileResult::failure(work.id, 1, elapsed)
   232→            }
   233→        }
   234→    }
   235→
   236→    /// Worker thread main loop
   237→    pub fn run(&self) {
   238→        while self.active.load(Ordering::Relaxed) {
   239→            match self.queue.dequeue() {
   240→                Some(work) => {
   241→                    let result = self.compile(work);
   242→                    self.queue.add_result(result);
   243→                }
   244→                None => {
   245→                    // Idle
   246→                    thread::sleep(std::time::Duration::from_millis(1));
   247→                }
   248→            }
   249→        }
   250→    }
   251→
   252→    pub fn stop(&self) {
   253→        self.active.store(false, Ordering::Relaxed);
   254→    }
   255→}
