   257→/// ParallelCompiler: Main coordinator for 4 workers
   258→pub struct ParallelCompiler {
   259→    num_workers: u32,
   260→    state: Arc<SharedState>,
   261→    queue: WorkQueue,
   262→}
   263→
   264→impl ParallelCompiler {
   265→    pub fn new() -> Self {
   266→        ParallelCompiler::with_workers(4)
   267→    }
   268→
   269→    pub fn with_workers(num_workers: u32) -> Self {
   270→        let state = Arc::new(SharedState::new(1024)); // 1K token cache
   271→        let queue = WorkQueue::new();
   272→
   273→        ParallelCompiler {
   274→            num_workers,
   275→            state,
   276→            queue,
   277→        }
   278→    }
   279→
   280→    /// Submit work items for compilation
   281→    pub fn submit(&self, items: Vec<WorkItem>) -> Result<(), String> {
   282→        for item in items {
   283→            self.queue.enqueue(item)?;
   284→        }
   285→        Ok(())
   286→    }
   287→
   288→    /// Compile in parallel (blocking)
   289→    pub fn compile_parallel(&self, source_codes: Vec<String>) -> Vec<CompileResult> {
   290→        // Prepare work items
   291→        let mut work_items = Vec::new();
   292→        for (idx, source) in source_codes.iter().enumerate() {
   293→            work_items.push(WorkItem::new(idx as u64, source.clone()));
   294→        }
   295→
   296→        // Submit to queue
   297→        let _ = self.submit(work_items);
   298→
   299→        // Spawn worker threads
   300→        let mut handles = vec![];
   301→        for worker_id in 0..self.num_workers {
   302→            let state = Arc::clone(&self.state);
   303→            let queue = self.queue.clone();
   304→
   305→            let handle = thread::spawn(move || {
   306→                let worker = Worker::new(worker_id, state, queue);
   307→                worker.run();
   308→            });
   309→
   310→            handles.push(handle);
   311→        }
   312→
   313→        // Wait for all work to complete
   314→        while !self.queue.is_empty() {
   315→            thread::sleep(std::time::Duration::from_millis(10));
   316→        }
   317→
   318→        // Collect results before stopping workers
   319→        let results = self.queue.get_results();
   320→
   321→        // Give workers a chance to see empty queue and exit gracefully
   322→        thread::sleep(std::time::Duration::from_millis(50));
   323→
   324→        // Wait for all worker threads to finish (prevents thread leaks)
   325→        for handle in handles {
   326→            let _ = handle.join();  // Join thread, ignoring panics
   327→        }
   328→
   329→        results
   330→    }
   331→
   332→    /// Non-blocking submit with callback
   333→    pub fn submit_async(&self, items: Vec<WorkItem>) -> Result<(), String> {
   334→        self.submit(items)
   335→    }
   336→
   337→    /// Get cache hit rate
   338→    pub fn cache_hit_rate(&self) -> f64 {
   339→        self.state.token_cache_hit_rate()
   340→    }
   341→
   342→    /// Get compilation metrics
   343→    pub fn get_metrics(&self) -> (u64, u64) {
   344→        self.state.get_metrics()
   345→    }
   346→
   347→    /// Get all compilation results
   348→    pub fn get_results(&self) -> Vec<CompileResult> {
   349→        self.queue.get_results()
   350→    }
   351→
   352→    /// Clear internal state
   353→    pub fn clear(&self) {
   354→        self.state.clear();
   355→    }
   356→}
   357→
   358→impl Default for ParallelCompiler {
   359→    fn default() -> Self {
   360→        Self::new()
   361→    }
   362→}
