     1→// Shared Memory & Token Caching for Parallel Compilation
     2→// Enables 4 worker threads to share compilation artifacts
     3→
     4→use std::collections::{HashMap, VecDeque};
     5→use std::sync::{Arc, Mutex};
     6→use std::sync::atomic::{AtomicU64, Ordering};
     7→
     8→/// Token: Represents a lexical token in source code
     9→#[derive(Debug, Clone, Eq, PartialEq, Hash)]
    10→pub struct Token {
    11→    pub id: u64,
    12→    pub token_type: u8,  // 0=keyword, 1=identifier, 2=literal, etc
    13→    pub value: String,
    14→    pub line: u32,
    15→    pub column: u32,
    16→}
    17→
    18→impl Token {
    19→    pub fn new(id: u64, token_type: u8, value: String, line: u32, column: u32) -> Self {
    20→        Token {
    21→            id,
    22→            token_type,
    23→            value,
    24→            line,
    25→            column,
    26→        }
    27→    }
    28→}
    29→
    30→/// TokenCache: Shared cache for frequently tokenized strings
    31→/// Reduces re-tokenization overhead (O(1) lookup via HashMap)
    32→pub struct TokenCache {
    33→    tokens: HashMap<u64, Token>,
    34→    insertion_order: VecDeque<u64>,  // Track insertion order for LRU eviction
    35→    capacity: usize,
    36→    hits: u64,      // Now plain u64 (Mutex already provides exclusive access)
    37→    misses: u64,
    38→}
    39→
    40→impl TokenCache {
    41→    pub fn new(capacity: usize) -> Self {
    42→        TokenCache {
    43→            tokens: HashMap::with_capacity(capacity),
    44→            insertion_order: VecDeque::with_capacity(capacity),
    45→            capacity,
    46→            hits: 0,
    47→            misses: 0,
    48→        }
    49→    }
    50→
    51→    /// Lookup token by ID (O(1) - HashMap lookup)
    52→    pub fn lookup(&mut self, token_id: u64) -> Option<Token> {
    53→        match self.tokens.get(&token_id) {
    54→            Some(token) => {
    55→                self.hits += 1;
    56→                Some(token.clone())
    57→            }
    58→            None => {
    59→                self.misses += 1;
    60→                None
    61→            }
    62→        }
    63→    }
    64→
    65→    /// Insert token with automatic LRU capacity management (O(1) amortized)
    66→    pub fn insert(&mut self, token: Token) -> bool {
    67→        let token_id = token.id;
    68→
    69→        // If at capacity and token not already cached, evict oldest
    70→        if self.tokens.len() >= self.capacity && !self.tokens.contains_key(&token_id) {
    71→            if let Some(oldest_id) = self.insertion_order.pop_front() {
    72→                self.tokens.remove(&oldest_id);
    73→            }
    74→        }
    75→
    76→        // Insert token
    77→        self.tokens.insert(token_id, token);
    78→
    79→        // Track insertion order (only if new token)
    80→        if self.insertion_order.len() < self.capacity {
    81→            self.insertion_order.push_back(token_id);
    82→        }
    83→
    84→        true
    85→    }
    86→
    87→    pub fn hit_rate(&self) -> f64 {
    88→        let total = self.hits + self.misses;
    89→        if total == 0 { 0.0 } else { self.hits as f64 / total as f64 }
    90→    }
    91→
    92→    pub fn stats(&self) -> (u64, u64, f64) {
    93→        let total = self.hits + self.misses;
    94→        let rate = if total == 0 { 0.0 } else { self.hits as f64 / total as f64 };
    95→        (self.hits, self.misses, rate)
    96→    }
    97→
    98→    pub fn clear(&mut self) {
    99→        self.tokens.clear();
   100→        self.insertion_order.clear();
   101→    }
   102→
   103→    pub fn len(&self) -> usize {
   104→        self.tokens.len()
   105→    }
   106→
   107→    pub fn is_empty(&self) -> bool {
   108→        self.tokens.is_empty()
   109→    }
   110→}
   111→
   112→/// Variable: Represents a defined variable in compilation
   113→#[derive(Debug, Clone)]
   114→pub struct Variable {
   115→    pub name: String,
   116→    pub var_type: String,
   117→    pub scope: u32,
   118→    pub value: Option<String>,
   119→}
   120→
   121→/// Function: Represents a defined function in compilation
   122→#[derive(Debug, Clone)]
   123→pub struct Function {
   124→    pub name: String,
   125→    pub params: Vec<(String, String)>, // (name, type)
   126→    pub return_type: String,
   127→    pub scope: u32,
   128→}
   129→
   130→/// SharedState: Thread-safe shared compilation state
   131→/// All 4 workers can read/write to these shared structures (O(1) lookups via HashMap)
   132→pub struct SharedState {
   133→    pub token_cache: Arc<Mutex<TokenCache>>,
   134→    pub variables: Arc<Mutex<HashMap<String, Variable>>>,
   135→    pub functions: Arc<Mutex<HashMap<String, Function>>>,
   136→    pub errors: Arc<Mutex<Vec<String>>>,
   137→    total_tokens: AtomicU64,
   138→    total_time_ns: AtomicU64,
   139→}
   140→
   141→impl SharedState {
   142→    pub fn new(cache_capacity: usize) -> Self {
   143→        SharedState {
   144→            token_cache: Arc::new(Mutex::new(TokenCache::new(cache_capacity))),
   145→            variables: Arc::new(Mutex::new(HashMap::new())),
   146→            functions: Arc::new(Mutex::new(HashMap::new())),
   147→            errors: Arc::new(Mutex::new(Vec::new())),
   148→            total_tokens: AtomicU64::new(0),
   149→            total_time_ns: AtomicU64::new(0),
   150→        }
   151→    }
   152→
   153→    /// Add variable to shared state (O(1) HashMap insert)
   154→    pub fn add_variable(&self, var: Variable) -> Result<(), String> {
   155→        match self.variables.lock() {
   156→            Ok(mut vars) => {
   157→                vars.insert(var.name.clone(), var);
   158→                Ok(())
   159→            }
   160→            Err(e) => Err(format!("Failed to lock variables: {}", e)),
   161→        }
   162→    }
   163→
   164→    /// Lookup variable by name (O(1) HashMap get)
   165→    pub fn lookup_variable(&self, name: &str) -> Option<Variable> {
   166→        match self.variables.lock() {
   167→            Ok(vars) => vars.get(name).cloned(),
   168→            Err(_) => None,
   169→        }
   170→    }
   171→
   172→    /// Add function to shared state (O(1) HashMap insert)
   173→    pub fn add_function(&self, func: Function) -> Result<(), String> {
   174→        match self.functions.lock() {
   175→            Ok(mut funcs) => {
   176→                funcs.insert(func.name.clone(), func);
   177→                Ok(())
   178→            }
   179→            Err(e) => Err(format!("Failed to lock functions: {}", e)),
   180→        }
   181→    }
   182→
   183→    /// Lookup function by name (O(1) HashMap get)
   184→    pub fn lookup_function(&self, name: &str) -> Option<Function> {
   185→        match self.functions.lock() {
   186→            Ok(funcs) => funcs.get(name).cloned(),
   187→            Err(_) => None,
   188→        }
   189→    }
   190→
   191→    /// Record error
   192→    pub fn record_error(&self, error: String) {
   193→        if let Ok(mut errs) = self.errors.lock() {
   194→            errs.push(error);
   195→        }
   196→    }
   197→
   198→    /// Get all variables as Vec
   199→    pub fn get_variables(&self) -> Vec<Variable> {
   200→        match self.variables.lock() {
   201→            Ok(vars) => vars.values().cloned().collect(),
   202→            Err(_) => Vec::new(),
   203→        }
   204→    }
   205→
   206→    /// Get all functions as Vec
   207→    pub fn get_functions(&self) -> Vec<Function> {
   208→        match self.functions.lock() {
   209→            Ok(funcs) => funcs.values().cloned().collect(),
   210→            Err(_) => Vec::new(),
   211→        }
   212→    }
   213→
   214→    /// Get all errors
   215→    pub fn get_errors(&self) -> Vec<String> {
   216→        match self.errors.lock() {
   217→            Ok(errs) => errs.clone(),
   218→            Err(_) => Vec::new(),
   219→        }
   220→    }
   221→
   222→    /// Update total metrics
   223→    pub fn update_metrics(&self, tokens: u64, time_ns: u64) {
   224→        self.total_tokens.fetch_add(tokens, Ordering::Relaxed);
   225→        self.total_time_ns.fetch_add(time_ns, Ordering::Relaxed);
   226→    }
   227→
   228→    /// Get metrics
   229→    pub fn get_metrics(&self) -> (u64, u64) {
   230→        (
   231→            self.total_tokens.load(Ordering::Relaxed),
   232→            self.total_time_ns.load(Ordering::Relaxed),
   233→        )
   234→    }
   235→
   236→    /// Get token cache hit rate
   237→    pub fn token_cache_hit_rate(&self) -> f64 {
   238→        match self.token_cache.lock() {
   239→            Ok(cache) => cache.hit_rate(),
   240→            Err(_) => 0.0,
   241→        }
   242→    }
   243→
   244→    pub fn clear(&self) {
   245→        if let Ok(mut cache) = self.token_cache.lock() {
   246→            cache.clear();
   247→        }
   248→        if let Ok(mut vars) = self.variables.lock() {
   249→            vars.clear();  // HashMap::clear()
   250→        }
   251→        if let Ok(mut funcs) = self.functions.lock() {
   252→            funcs.clear();  // HashMap::clear()
   253→        }
   254→        if let Ok(mut errs) = self.errors.lock() {
   255→            errs.clear();
   256→        }
   257→    }
   258→}
