   260→/// WorkItem: Unit of work for parallel compilation
   261→#[derive(Debug, Clone)]
   262→pub struct WorkItem {
   263→    pub id: u64,
   264→    pub source_code: String,
   265→    pub worker_id: u32,
   266→    pub status: WorkStatus,
   267→}
   268→
   269→#[derive(Debug, Clone, PartialEq)]
   270→pub enum WorkStatus {
   271→    Pending,
   272→    InProgress,
   273→    Completed,
   274→    Failed(String),
   275→}
   276→
   277→impl WorkItem {
   278→    pub fn new(id: u64, source_code: String) -> Self {
   279→        WorkItem {
   280→            id,
   281→            source_code,
   282→            worker_id: 0,
   283→            status: WorkStatus::Pending,
   284→        }
   285→    }
   286→
   287→    pub fn start(&mut self, worker_id: u32) {
   288→        self.worker_id = worker_id;
   289→        self.status = WorkStatus::InProgress;
   290→    }
   291→
   292→    pub fn complete(&mut self) {
   293→        self.status = WorkStatus::Completed;
   294→    }
   295→
   296→    pub fn fail(&mut self, reason: String) {
   297→        self.status = WorkStatus::Failed(reason);
   298→    }
   299→
   300→    pub fn is_pending(&self) -> bool {
   301→        self.status == WorkStatus::Pending
   302→    }
   303→
   304→    pub fn is_in_progress(&self) -> bool {
   305→        self.status == WorkStatus::InProgress
   306→    }
   307→
   308→    pub fn is_completed(&self) -> bool {
   309→        self.status == WorkStatus::Completed
   310→    }
   311→
   312→    pub fn is_failed(&self) -> bool {
   313→        matches!(self.status, WorkStatus::Failed(_))
   314→    }
   315→}
