   784→fn interactive_mode() {
   785→    let mut vm = VM::new();
   786→
   787→    println!("\n╭─ Interactive FreeLang Console ────────────────────────╮");
   788→    println!("│ Type commands: set <var> <value>, get <var>, test  │");
   789→    println!("│ Type 'exit' to quit                                │");
   790→    println!("╰───────────────────────────────────────────────────────╯\n");
   791→
   792→    loop {
   793→        print!("fl> ");
   794→        io::stdout().flush().unwrap();
   795→
   796→        let mut input = String::new();
   797→        io::stdin().read_line(&mut input).unwrap();
   798→
   799→        let input = input.trim();
   800→        if input == "exit" {
   801→            println!("Goodbye!");
   802→            break;
   803→        }
   804→
   805→        let parts: Vec<&str> = input.split_whitespace().collect();
   806→        match parts.as_slice() {
   807→            ["set", var, value] => {
   808→                if let Ok(n) = value.parse::<i64>() {
   809→                    vm.set_variable(var.to_string(), Value::Integer(n));
   810→                    println!("Set {} = {}", var, n);
   811→                } else {
   812→                    vm.set_variable(var.to_string(), Value::String(value.to_string()));
   813→                    println!("Set {} = \"{}\"", var, value);
   814→                }
   815→            }
   816→            ["get", var] => {
   817→                if let Some(val) = vm.get_variable(var) {
   818→                    println!("{} = {}", var, val.to_string());
   819→                } else {
   820→                    println!("Variable {} not found", var);
   821→                }
   822→            }
   823→            ["test"] => {
   824→                let mut validator = Challenge14Validator::new();
   825→                validator.run_all_tests();
   826→                validator.validate_all_rules();
   827→            }
   828→            ["help"] => {
   829→                println!("Commands:");
   830→                println!("  set <var> <value>  - Set variable");
   831→                println!("  get <var>          - Get variable");
   832→                println!("  test               - Run tests");
   833→                println!("  exit               - Exit");
   834→            }
   835→            _ => println!("Unknown command. Type 'help' for usage."),
   836→        }
   837→    }
   838→}
